Here are several ways to sort a list in different programming languages:

## Python

### Using built-in `sorted()` function:
```python
def sort_list(lst):
    """Returns a new sorted list without modifying the original"""
    return sorted(lst)

# Usage
numbers = [64, 34, 25, 12, 22, 11, 90]
sorted_numbers = sort_list(numbers)
print(sorted_numbers)  # [11, 12, 22, 25, 34, 64, 90]
```

### Using `.sort()` method (in-place sorting):
```python
def sort_list_inplace(lst):
    """Sorts the list in-place and returns it"""
    lst.sort()
    return lst

# Usage
numbers = [64, 34, 25, 12, 22, 11, 90]
sort_list_inplace(numbers)
print(numbers)  # [11, 12, 22, 25, 34, 64, 90]
```

### Custom sorting with parameters:
```python
def sort_list_custom(lst, reverse=False, key=None):
    """Flexible sorting function with optional parameters"""
    return sorted(lst, reverse=reverse, key=key)

# Usage examples
numbers = [64, 34, 25, 12, 22, 11, 90]
words = ["apple", "pie", "Washington", "book"]

# Ascending order
print(sort_list_custom(numbers))  # [11, 12, 22, 25, 34, 64, 90]

# Descending order
print(sort_list_custom(numbers, reverse=True))  # [90, 64, 34, 25, 22, 12, 11]

# Sort by length
print(sort_list_custom(words, key=len))  # ['pie', 'book', 'apple', 'Washington']
```

## JavaScript

```javascript
function sortList(arr, compareFunction = null) {
    // Create a copy to avoid modifying the original array
    const sortedArray = [...arr];

    if (compareFunction) {
        return sortedArray.sort(compareFunction);
    } else {
        return sortedArray.sort();
    }
}

// Usage
const numbers = [64, 34, 25, 12, 22, 11, 90];
const words = ["apple", "pie", "Washington", "book"];

// Sort numbers (need custom compare function for proper numeric sorting)
console.log(sortList(numbers, (a, b) => a - b)); // [11, 12, 22, 25, 34, 64, 90]

// Sort strings alphabetically
console.log(sortList(words)); // ["Washington", "apple", "book", "pie"]

// Sort in descending order
console.log(sortList(numbers, (a, b) => b - a)); // [90, 64, 34, 25, 22, 12, 11]
```

## Manual Implementation (Bubble Sort)

If you want to implement sorting from scratch, here's a simple bubble sort:

```python
def bubble_sort(lst):
    """Implements bubble sort algorithm"""
    # Create a copy to avoid modifying the original list
    arr = lst.copy()
    n = len(arr)

    for i in range(n):
        # Flag to optimize - if no swaps occur, list is already sorted
        swapped = False

        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                # Swap elements
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True

        # If no swapping occurred, array is sorted
        if not swapped:
            break

    return arr

# Usage
numbers = [64, 34, 25, 12, 22, 11, 90]
sorted_numbers = bubble_sort(numbers)
print(sorted_numbers)  # [11, 12, 22, 25, 34, 64, 90]
```

